# --------------------------------------------------------------------------
# Envelope validation (section 1)
# --------------------------------------------------------------------------

def _fail(msg):
    raise BadEnvelope(msg)


def _int(x):
    if isinstance(x, bool) or not isinstance(x, int):
        _fail("integer required")
    return x


def _str(x):
    if not isinstance(x, str):
        _fail("string required")
    return x


def _list(x):
    if not isinstance(x, list):
        _fail("array required")
    return x


def _dict(x):
    if not isinstance(x, dict):
        _fail("object required")
    return x


def _exact(d, keys):
    if len(d) != len(keys):
        _fail("key set mismatch")
    for k in keys:
        if k not in d:
            _fail("missing key " + k)


def _pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            _fail("duplicate key")
        d[k] = v
    return d


def _constant(name):
    _fail("bad constant " + name)


def validate(doc):
    d = _dict(doc)
    _exact(d, ("version", "config", "events"))
    if _int(d["version"]) != 1:
        _fail("version")
    cfg = _dict(d["config"])
    _exact(cfg, ("accounts", "peers", "ttl_ms", "capacity"))

    accounts = _list(cfg["accounts"])
    if len(accounts) > 256:
        _fail("too many accounts")
    acct_ids = set()
    alias_owner = {}
    defaults = {}
    for a in accounts:
        a = _dict(a)
        _exact(a, ("id", "default", "aliases"))
        aid = _str(a["id"])
        if not ID_RE.fullmatch(aid):
            _fail("account id")
        if aid in acct_ids:
            _fail("duplicate account id")
        acct_ids.add(aid)
        aliases = _list(a["aliases"])
        la = len(aliases)
        if la < 1 or la > 8:
            _fail("alias count")
        seen = set()
        for al in aliases:
            al = _str(al)
            if len(al) > MAX_URI_LEN:
                _fail("alias too long")
            c, _tel = canon_uri(al)
            if c is None or c != al:
                _fail("alias not canonical: " + al)
            if al == ANON:
                _fail("anonymous alias")
            if al in seen:
                _fail("duplicate alias")
            if al in alias_owner:
                _fail("alias owned twice")
            seen.add(al)
            alias_owner[al] = aid
        dflt = _str(a["default"])
        if dflt not in seen:
            _fail("default not an alias")
        defaults[aid] = dflt

    peers = _list(cfg["peers"])
    lp = len(peers)
    if lp < 1 or lp > 256:
        _fail("peer count")
    peer_mode = {}
    peer_accounts = {}
    for p in peers:
        p = _dict(p)
        _exact(p, ("id", "mode", "accounts"))
        pid = _str(p["id"])
        if not ID_RE.fullmatch(pid):
            _fail("peer id")
        if pid in peer_mode:
            _fail("duplicate peer id")
        mode = _str(p["mode"])
        if mode != "access" and mode != "relay":
            _fail("peer mode")
        accs = _list(p["accounts"])
        if mode == "access":
            if accs:
                _fail("access peer accounts")
            peer_accounts[pid] = frozenset()
        else:
            if len(accs) > 256:
                _fail("too many relay accounts")
            s = set()
            for x in accs:
                x = _str(x)
                if x not in acct_ids:
                    _fail("unknown relay account")
                if x in s:
                    _fail("duplicate relay account")
                s.add(x)
            peer_accounts[pid] = frozenset(s)
        peer_mode[pid] = mode

    ttl = _int(cfg["ttl_ms"])
